const cw = new CloudWatchClient({});
const m = await cw.send(new ListMetricsCommand({}));
// compute sums for biz-ridge
for (const metric of m.Metrics) {
  const dims = Object.fromEntries(metric.Dimensions.map(d=>[d.Name,d.Value]));
  const r = await cw.send(new GetMetricDataCommand({
    StartTime: new Date(cat.periodStart), EndTime: new Date(cat.periodEnd), ScanBy:'TimestampAscending',
    MetricDataQueries:[{Id:'series',ReturnData:true,MetricStat:{Metric:{Namespace:metric.Namespace,MetricName:metric.MetricName,Dimensions:metric.Dimensions},Period:cat.usagePeriod,Stat:'Sum'}}]
  }));
  const vals = (r.MetricDataResults||[]).flatMap(x=>x.Values||[]);
  const sum = vals.reduce((a,b)=>a+b,0);
  console.log(dims.BusinessId, dims.CustomerId, dims.DimensionId, 'sum=', sum, 'points=', vals.length);
}
