                ),
            );
            if (dimension?.paymentSchedule === PaymentSchedule.upfront) {
                const billingMSStartDate = proratedStartDate ? proratedStartDate : startDate;
                const billingMSSeconds: number = Math.round(Math.abs(endDate.getTime() - billingMSStartDate.getTime()));
                const billingMSSecondsInBillingCycle = Offering.determineBillingSecondsInBillingCycle({
                    date: billingMSStartDate,
                    billingCycle: offeringInstance?.billingCycle,
                }) as number;
                unitCost = Math.round(100 * unitCost * (billingMSSeconds / billingMSSecondsInBillingCycle)) / 100;
            }

            // Only usage beyond a finite, exhausted allowance is chargeable. An unlimited
            // ('inf') allowance, an allowance the customer has not exhausted, or a plan that
            // forbids overage all leave nothing to charge for on this dimension.
            const { usageEntitlement, overageAllowed } = dimension;
            let chargeableTotal = dimensionTotals[dimensionId];
            if (usageEntitlement !== undefined && usageEntitlement !== null) {
                if (usageEntitlement === 'inf' || overageAllowed === overageAllowedEnum.false) {
                    chargeableTotal = 0;
                } else {
                    chargeableTotal = Math.max(0, dimensionTotals[dimensionId] - Number(usageEntitlement));
                }
            }

            // A dimension earns a line whenever the customer owes something on it. A dimension
            // the plan prices at zero earns a line too, unless the invoice settings hide free
            // dimensions.
            const isFreeDimension = unitCost === 0;
            if (isFreeDimension) {
                if (offeringInstance?.settings?.freeDimensionOnInvoice === FreeDimensionOnInvoice.hide) {
                    return;
                }
            } else if (chargeableTotal <= 0) {
                return;
